`timescale 1ns/1ps

// The grading testbench: three bits, so the whole range is walked
// twice over, and every step is checked for the one-bit property.
module tb;

  localparam int W = 3;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic rst_n = 1'b1;
  logic en    = 1'b0;
  logic [W-1:0] bin, gray;

  gray_counter #(.W(W)) dut (
    .clk(clk), .rst_n(rst_n), .en(en), .bin(bin), .gray(gray)
  );

  integer i;
  logic [W-1:0] prev;
  integer changed, worst;

  // One cycle: drive at the falling edge, return just after the rising
  // one, so what is read is what the edge produced.
  task tick(input logic e);
    begin
      @(negedge clk); en = e;
      @(posedge clk); #1;
    end
  endtask

  task reset;
    begin
      @(negedge clk); rst_n = 1'b0; en = 1'b0;
      @(posedge clk); #1;
      rst_n = 1'b1;
    end
  endtask

  // How many bits differ between two values.
  function automatic integer bits_differing(input [W-1:0] a, input [W-1:0] b);
    integer k, c;
    begin
      c = 0;
      for (k = 0; k < W; k = k + 1) if (a[k] !== b[k]) c = c + 1;
      bits_differing = c;
    end
  endfunction

  logic [W-1:0] seen [0:7];
  integer dup, j;
  logic [W-1:0] b_wrap, g_wrap, b_held, g_held;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    // Walk the whole range twice, recording the worst single-step
    // change and the Gray codes of the first lap.
    reset();
    worst = 0;
    prev = gray;
    for (i = 0; i < 16; i = i + 1) begin
      tick(1'b1);
      changed = bits_differing(prev, gray);
      if (changed > worst) worst = changed;
      prev = gray;
      if (i < 8) seen[i] = gray;
    end

    // Every code of the first lap distinct?
    dup = 0;
    for (i = 0; i < 8; i = i + 1)
      for (j = i + 1; j < 8; j = j + 1)
        if (seen[i] === seen[j]) dup = dup + 1;

    // Wrap: seven steps from reset puts bin at 7, one more wraps to 0.
    reset();
    for (i = 0; i < 8; i = i + 1) tick(1'b1);
    b_wrap = bin;
    g_wrap = gray;

    // Disabled for a while, then enabled again.
    reset();
    tick(1'b1); tick(1'b1); tick(1'b1);
    tick(1'b0); tick(1'b0);
    b_held = bin;
    g_held = gray;

    $display("CHECK one_bit_per_step 1 %0d AT %0d", worst, $time);
    $display("CHECK all_codes_distinct 0 %0d AT %0d", dup, $time);
    $display("CHECK bin_wraps_to_zero 0 %0d AT %0d", b_wrap, $time);
    $display("CHECK gray_wraps_to_zero 0 %0d AT %0d", g_wrap, $time);
    $display("CHECK holds_binary_when_disabled 3 %0d AT %0d", b_held, $time);
    $display("CHECK holds_gray_when_disabled 2 %0d AT %0d", g_held, $time);
    $display("CHECK gray_of_three 2 %0d AT %0d", seen[2], $time);
    $display("CHECK gray_of_four 6 %0d AT %0d", seen[3], $time);
    $display("CHECK gray_of_seven 4 %0d AT %0d", seen[6], $time);
    $display("DONE 9");
    $finish;
  end

endmodule

