// A counter whose second output changes one bit at a time.
//
// Keeping the binary count as the state and converting is the whole
// trick: the conversion is combinational and costs W-1 XOR gates, and
// there is no Gray-code adder to design.

module gray_counter #(
    parameter int W = 4
) (
    input  logic         clk,
    input  logic         rst_n,    // synchronous, active low
    input  logic         en,       // advance on this edge
    output logic [W-1:0] bin,      // the ordinary count
    output logic [W-1:0] gray      // the same count in Gray code
);

    always_ff @(posedge clk) begin
        if (!rst_n)   bin <= '0;
        else if (en)  bin <= bin + 1'b1;
    end

    // n ^ (n >> 1): adjacent values of n differ in exactly one bit of
    // the result.
    assign gray = bin ^ (bin >> 1);

endmodule
